import subprocess
import sys
from pathlib import Path

NEW_FILES = {
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbAction.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Modelo de ação estruturada produzido pelo QsbIntentParser a partir do\n * texto digitado no Modo Texto da QSB. É o "JSON inteligente" da\n * arquitetura pedida pelo usuário: uma representação estruturada e\n * tipada da intenção reconhecida, que o chamador (OseWidgetView)\n * traduz para um Intent real do Android e executa.\n *\n * Fica em memória como sealed class em vez de String JSON serializada\n * de propósito — mesmo conceito (ação estruturada, não texto livre),\n * mas sem overhead de serialização/parsing dentro do mesmo processo.\n * Se algum dia for preciso persistir ou logar a ação (histórico de\n * comandos, por exemplo), dá pra serializar QsbAction para JSON depois\n * sem mudar o parser.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport java.io.Serializable\n\n/**\n * Serializable propositalmente: precisa atravessar um Intent extra ao\n * abrir XaulinXsQsbPermissionActivity (pedido de permissão de\n * contatos em Activity dedicada — ver comentário lá) e voltar depois\n * que o usuário concede/nega, para reexecutar o comando original sem\n * o usuário digitar de novo.\n */\nsealed class QsbAction : Serializable {\n\n    /** Abrir um app pelo nome, sem ação específica dentro dele. */\n    data class OpenApp(val appQuery: String) : QsbAction()\n\n    /** Ligar para um número discado diretamente no texto. */\n    data class CallNumber(val number: String) : QsbAction()\n\n    /** Ligar para um contato salvo, resolvido por nome. */\n    data class CallContact(val contactQuery: String) : QsbAction()\n\n    /** Mandar mensagem no WhatsApp para um número discado diretamente. */\n    data class WhatsAppNumber(val number: String, val message: String) : QsbAction()\n\n    /** Mandar mensagem no WhatsApp para um contato salvo, resolvido por nome. */\n    data class WhatsAppContact(val contactQuery: String, val message: String) : QsbAction()\n\n    /** Mandar SMS para um número discado diretamente. */\n    data class SmsNumber(val number: String, val message: String) : QsbAction()\n\n    /** Mandar SMS para um contato salvo, resolvido por nome. */\n    data class SmsContact(val contactQuery: String, val message: String) : QsbAction()\n\n    /** Abrir um app e, dentro dele, disparar uma pesquisa por [query]. */\n    data class SearchInApp(val appQuery: String, val query: String) : QsbAction()\n\n    /** Nenhum comando reconhecido — chamador decide o fallback (Modo Web / texto livre). */\n    data object Unrecognized : QsbAction()\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbIntentParser.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * "QSB Super Inteligente" — parser de linguagem natural do Modo Texto.\n *\n * Decisão de arquitetura (substitui a ideia original de usar a lib\n * nativa do LatinIME, libjni_latinime.so): aquela lib é o motor de\n * autocorreção/previsão de teclado do AOSP (BinaryDictionary +\n * ProximityInfo + DicTraverseSession — sugestão por n-gramas e\n * distância de edição). Ela não tem, e não foi desenhada para ter,\n * nenhum conceito de "ação" ou "intenção" — só sabe dizer qual palavra\n * do dicionário é estatisticamente mais provável a partir de outra ou\n * de um toque impreciso. Linkar JNI nela para reconhecer comandos\n * seria trabalho extra (bridge JNI, empacotar arquivo de dicionário\n * .dict, gerenciar ProximityInfo do layout) sem ganho nenhum sobre um\n * parser de regras leve — na real, pioraria: a lib tentaria\n * "corrigir"/prever palavras dentro do comando, e não extrair a ação.\n *\n * Este parser resolve o que o usuário pediu de fato — frase em\n * linguagem natural -> ação estruturada (QsbAction) -> Intent — com\n * reconhecimento de verbo + entidade via regex, 100% on-device, sem\n * dependência nativa nova. Fica aberto para, no futuro, ganhar\n * tolerância a erro de digitação via TextServicesManager/\n * SpellCheckerSession (serviço de correção ortográfica do próprio\n * Android), sem precisar reimplementar o LatinIME dentro do launcher.\n *\n * Cobertura desta primeira versão (ordem de tentativa = ordem de\n * prioridade, primeiro match vence):\n *   1) WhatsApp para contato/número, com mensagem\n *   2) SMS para contato/número, com mensagem\n *   3) Ligar para contato/número\n *   4) Abrir <app> e pesquisar <algo> dentro dele\n *   5) Abrir <app>\n * Qualquer texto que não bata com nenhum padrão -> QsbAction.Unrecognized.\n *\n * Requisito do usuário respeitado: nenhum destes ramos cai para\n * browser/app genérico como fallback — cada um resolve uma ação\n * concreta, e a decisão de fallback só acontece em Unrecognized,\n * fora deste arquivo (OseWidgetView).\n */\npackage com.xaulinxs.customizations.qsb\n\nobject QsbIntentParser {\n\n    // Verbos aceitos por categoria, todos minúsculos (comparação é\n    // sempre contra o texto já lowercased). Mantidos como listas\n    // simples e não regex "|" gigante para ficar fácil de estender\n    // sem risco de quebrar grupos de captura.\n    private val OPEN_VERBS = listOf("abrir", "abre", "abrir o", "abre o", "abrir a", "abre a", "open")\n    private val CALL_VERBS =\n        listOf(\n            "ligar para", "ligue para", "liga para", "liga pro", "ligar pro",\n            "chamar", "chama",\n            "faz ligação para", "faz ligação pro", "fazer ligação para", "fazer ligação pro",\n            "faz uma ligação para", "faz uma ligação pro",\n            "disca para", "disca pro", "discar para", "discar pro",\n        )\n    private val WHATSAPP_TRIGGERS =\n        listOf("whatsapp", "whats app", "zap", "zapzap")\n    private val SMS_TRIGGERS = listOf("sms", "mensagem de texto")\n    private val SEARCH_VERBS = listOf("pesquisar", "pesquisa", "procurar", "procura", "buscar", "busca")\n\n    // Aceita "pro", "para o", "pra", "para", "com" antes do destinatário —\n    // cobre as variações mais comuns de fala/escrita informal em pt-BR.\n    private val RECIPIENT_CONNECTORS = listOf(" pro ", " para o ", " pra ", " para ", " com ")\n\n    // "dizendo", "falando", "escrito", ou dois pontos — separam\n    // destinatário do corpo da mensagem em comandos de WhatsApp/SMS.\n    private val MESSAGE_CONNECTORS = listOf(" dizendo ", " falando ", " escrito ", " escrevendo ", ": ")\n\n    // Só dígitos, espaços, parênteses, hífen e \'+\' — o suficiente para\n    // reconhecer um número discado diretamente no texto (não valida\n    // DDD/formato, só decide "isso parece um número" vs "isso é um nome").\n    private val NUMBER_REGEX = Regex("^[+\\\\d][\\\\d\\\\s()-]{6,}$")\n\n    /**\n     * Ponto de entrada único do parser. [rawInput] é o texto exatamente\n     * como o usuário digitou no campo do Modo Texto, sem normalização\n     * prévia feita pelo chamador.\n     */\n    @JvmStatic\n    fun parse(rawInput: String): QsbAction {\n        val trimmed = rawInput.trim()\n        if (trimmed.isEmpty()) return QsbAction.Unrecognized\n        val lower = trimmed.lowercase()\n\n        parseWhatsApp(trimmed, lower)?.let { return it }\n        parseSms(trimmed, lower)?.let { return it }\n        parseCall(trimmed, lower)?.let { return it }\n        parseSearchInApp(trimmed, lower)?.let { return it }\n        parseOpenApp(trimmed, lower)?.let { return it }\n\n        return QsbAction.Unrecognized\n    }\n\n    // ------------------------------------------------------------------\n    // WhatsApp: "manda mensagem no whatsapp pro <alguem> dizendo <texto>"\n    // Ordem de busca dos gatilhos é flexível de propósito: o usuário pode\n    // falar "whatsapp" antes ou depois do destinatário ("manda whatsapp\n    // pra Ana dizendo oi" ou "manda pra Ana no whatsapp dizendo oi").\n    // ------------------------------------------------------------------\n    private fun parseWhatsApp(original: String, lower: String): QsbAction? {\n        if (WHATSAPP_TRIGGERS.none { lower.contains(it) }) return null\n\n        val (recipientRaw, messageRaw) = splitRecipientAndMessage(original, lower) ?: return null\n        // Remove os próprios gatilhos de "whatsapp" do texto do\n        // destinatário, caso tenham ficado colados (ex.: "no whatsapp").\n        val recipient = stripTriggerWords(recipientRaw, WHATSAPP_TRIGGERS)\n        if (recipient.isBlank()) return null\n\n        return if (looksLikeNumber(recipient)) {\n            QsbAction.WhatsAppNumber(normalizeNumber(recipient), messageRaw)\n        } else {\n            QsbAction.WhatsAppContact(recipient, messageRaw)\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // SMS: mesmo formato do WhatsApp, gatilho "sms" / "mensagem de texto"\n    // em vez de "whatsapp". Verificado depois do WhatsApp de propósito —\n    // "manda mensagem" sozinho (sem "sms" nem "whatsapp") não deve cair\n    // aqui, só quando o gatilho SMS aparece explicitamente.\n    // ------------------------------------------------------------------\n    private fun parseSms(original: String, lower: String): QsbAction? {\n        if (SMS_TRIGGERS.none { lower.contains(it) }) return null\n\n        val (recipientRaw, messageRaw) = splitRecipientAndMessage(original, lower) ?: return null\n        val recipient = stripTriggerWords(recipientRaw, SMS_TRIGGERS)\n        if (recipient.isBlank()) return null\n\n        return if (looksLikeNumber(recipient)) {\n            QsbAction.SmsNumber(normalizeNumber(recipient), messageRaw)\n        } else {\n            QsbAction.SmsContact(recipient, messageRaw)\n        }\n    }\n\n    /**\n     * Extrai destinatário e corpo da mensagem de um comando do tipo\n     * "<verbo> mensagem [no <canal>] pro <destinatário> dizendo <corpo>".\n     * O corpo é opcional: se não houver conector de mensagem, o\n     * destinatário é o resto do texto e o corpo fica vazio (o app\n     * de destino abre com o campo de mensagem em branco, pronto pra\n     * o usuário digitar).\n     */\n    private fun splitRecipientAndMessage(original: String, lower: String): Pair<String, String>? {\n        val connectorIndex =\n            RECIPIENT_CONNECTORS\n                .map { connector -> connector to lower.indexOf(connector) }\n                .filter { (_, index) -> index >= 0 }\n                .minByOrNull { (_, index) -> index }\n                ?: return null\n        val (connector, index) = connectorIndex\n\n        val afterConnector = original.substring(index + connector.length)\n        val afterConnectorLower = lower.substring(index + connector.length)\n\n        val messageConnectorIndex =\n            MESSAGE_CONNECTORS\n                .map { connector2 -> connector2 to afterConnectorLower.indexOf(connector2) }\n                .filter { (_, idx) -> idx >= 0 }\n                .minByOrNull { (_, idx) -> idx }\n\n        return if (messageConnectorIndex != null) {\n            val (msgConnector, msgIndex) = messageConnectorIndex\n            val recipient = afterConnector.substring(0, msgIndex).trim()\n            val message = afterConnector.substring(msgIndex + msgConnector.length).trim()\n            recipient to message\n        } else {\n            afterConnector.trim() to ""\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Ligação: "ligar para <contato ou número>"\n    // ------------------------------------------------------------------\n    private fun parseCall(original: String, lower: String): QsbAction? {\n        val verb = CALL_VERBS.firstOrNull { lower.startsWith(it + " ") } ?: return null\n        val target = original.substring(verb.length).trim()\n        if (target.isBlank()) return null\n\n        return if (looksLikeNumber(target)) {\n            QsbAction.CallNumber(normalizeNumber(target))\n        } else {\n            QsbAction.CallContact(target)\n        }\n    }\n\n    // ------------------------------------------------------------------\n    // Pesquisa dentro de app: "abrir <app> e pesquisar <algo>"\n    // Checado ANTES de parseOpenApp: sem essa ordem, "abrir chrome e\n    // pesquisar gatos" seria capturado por parseOpenApp com appQuery\n    // = "chrome e pesquisar gatos" (nome de app inválido, sem resolver\n    // a pesquisa em si).\n    // ------------------------------------------------------------------\n    private fun parseSearchInApp(original: String, lower: String): QsbAction? {\n        val openVerb = OPEN_VERBS.firstOrNull { lower.startsWith(it + " ") } ?: return null\n        val afterOpen = original.substring(openVerb.length).trim()\n        val afterOpenLower = afterOpen.lowercase()\n\n        val searchVerb = SEARCH_VERBS.firstOrNull { verb -> " $afterOpenLower ".contains(" $verb ") }\n            ?: return null\n        val searchIndex = afterOpenLower.indexOf(searchVerb)\n        if (searchIndex <= 0) return null\n\n        // Remove conectores soltos ("e", "e depois") entre o nome do\n        // app e o verbo de busca, sem exigir uma lista fixa de todas\n        // as combinações — corta na última ocorrência de " e " antes\n        // do verbo de busca, se existir.\n        var appPart = afterOpen.substring(0, searchIndex).trim()\n        val andIndex = appPart.lowercase().lastIndexOf(" e ")\n        appPart =\n            if (andIndex >= 0) {\n                appPart.substring(0, andIndex).trim()\n            } else {\n                // " e" pode ter ficado colado no fim (sem espaço depois)\n                // quando o corte caiu bem em cima do verbo de busca —\n                // rfind(" e ") com espaço nos dois lados não bate nesse\n                // caso, então trata separado.\n                appPart.removeSuffix(" e").trim()\n            }\n        // Descarta artigos/possessivos soltos que sobraram antes do\n        // nome de app de verdade (ex.: "meu navegador Chrome" ->\n        // "Chrome"). Nome de app na fala coloquial é tipicamente a\n        // última palavra dessa parte do texto.\n        appPart = appPart.substringAfterLast(\' \').trim()\n\n        var query = afterOpen.substring(searchIndex + searchVerb.length).trim()\n        // Remove preposição solta logo após o verbo de busca\n        // ("pesquisa POR gatos", "pesquisa SOBRE gatos") — sem isso a\n        // query levaria a preposição junto.\n        for (prep in listOf("por ", "sobre ", "de ")) {\n            if (query.lowercase().startsWith(prep)) {\n                query = query.substring(prep.length).trim()\n                break\n            }\n        }\n        if (appPart.isBlank() || query.isBlank()) return null\n\n        return QsbAction.SearchInApp(appPart, query)\n    }\n\n    // ------------------------------------------------------------------\n    // Abrir app: "abrir <app>" — mesmo comportamento (e resolução via\n    // AllAppsStore) que o QsbTextModeCommand original já tinha; o\n    // parser aqui só reconhece o padrão e devolve a query de app, quem\n    // resolve contra a lista de apps instalados continua sendo o\n    // chamador (evita este arquivo depender de AllAppsStore).\n    // ------------------------------------------------------------------\n    private fun parseOpenApp(original: String, lower: String): QsbAction? {\n        val verb = OPEN_VERBS.firstOrNull { lower.startsWith(it + " ") } ?: return null\n        val appQuery = original.substring(verb.length).trim()\n        if (appQuery.isBlank()) return null\n        return QsbAction.OpenApp(appQuery)\n    }\n\n    // ------------------------------------------------------------------\n    // Helpers\n    // ------------------------------------------------------------------\n\n    private fun looksLikeNumber(text: String): Boolean = NUMBER_REGEX.matches(stripNumberPrefix(text).trim())\n\n    /**\n     * Remove um prefixo falado como "número"/"numero" antes do dígito\n     * de fato ("liga pro número 11987654321" -> "11987654321") — sem\n     * isso, a palavra extra impede o NUMBER_REGEX de bater e o alvo\n     * cai incorretamente como nome de contato.\n     */\n    private fun stripNumberPrefix(text: String): String {\n        val trimmed = text.trim()\n        for (prefix in listOf("número ", "numero ", "num ")) {\n            if (trimmed.lowercase().startsWith(prefix)) return trimmed.substring(prefix.length).trim()\n        }\n        return trimmed\n    }\n\n    private fun normalizeNumber(text: String): String = stripNumberPrefix(text).filter { it.isDigit() || it == \'+\' }\n\n    private fun stripTriggerWords(text: String, triggers: List<String>): String {\n        var result = text\n        for (trigger in triggers) {\n            result = result.replace(Regex("(?i)\\\\bno $trigger\\\\b"), "")\n            result = result.replace(Regex("(?i)\\\\bpelo $trigger\\\\b"), "")\n            result = result.replace(Regex("(?i)\\\\b$trigger\\\\b"), "")\n        }\n        return result.trim().trim(\',\', \'.\', \' \')\n    }\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbContactResolver.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Resolve um nome de contato digitado no Modo Texto ("manda whatsapp\n * pra Ana") para um número de telefone real, via ContactsContract.\n *\n * Exige android.permission.READ_CONTACTS (adicionada ao Manifest por\n * este mesmo pacote de mudanças). Sem a permissão concedida, retorna\n * null e o chamador cai para o fluxo de pedir a permissão — nunca\n * finge sucesso nem usa dado incompleto.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport android.content.Context\nimport android.content.pm.PackageManager\nimport android.provider.ContactsContract\nimport androidx.core.content.ContextCompat\n\nobject QsbContactResolver {\n\n    data class ResolvedContact(val displayName: String, val phoneNumber: String)\n\n    @JvmStatic\n    fun hasContactsPermission(context: Context): Boolean =\n        ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_CONTACTS) ==\n            PackageManager.PERMISSION_GRANTED\n\n    /**\n     * Busca por nome (contém, case-insensitive) no provedor de\n     * contatos. Retorna o primeiro contato com telefone cadastrado que\n     * bate com [query], priorizando match exato de nome sobre "contém".\n     * Retorna null se não tiver permissão, não achar nada, ou o\n     * contato encontrado não tiver telefone.\n     */\n    @JvmStatic\n    fun resolve(context: Context, query: String): ResolvedContact? {\n        if (!hasContactsPermission(context)) return null\n        if (query.isBlank()) return null\n\n        val resolver = context.contentResolver\n        val projection =\n            arrayOf(\n                ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,\n                ContactsContract.CommonDataKinds.Phone.NUMBER,\n            )\n        val selection = "${ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME} LIKE ?"\n        val selectionArgs = arrayOf("%$query%")\n\n        var exactMatch: ResolvedContact? = null\n        var containsMatch: ResolvedContact? = null\n        val queryLower = query.trim().lowercase()\n\n        resolver\n            .query(\n                ContactsContract.CommonDataKinds.Phone.CONTENT_URI,\n                projection,\n                selection,\n                selectionArgs,\n                null,\n            )\n            ?.use { cursor ->\n                val nameIndex = cursor.getColumnIndex(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME)\n                val numberIndex = cursor.getColumnIndex(ContactsContract.CommonDataKinds.Phone.NUMBER)\n                if (nameIndex < 0 || numberIndex < 0) return@use\n\n                while (cursor.moveToNext()) {\n                    val name = cursor.getString(nameIndex) ?: continue\n                    val number = cursor.getString(numberIndex) ?: continue\n                    val candidate = ResolvedContact(name, number)\n\n                    if (name.trim().lowercase() == queryLower) {\n                        exactMatch = candidate\n                        // Match exato é o melhor resultado possível — não\n                        // precisa continuar varrendo o cursor.\n                        return@use\n                    }\n                    if (containsMatch == null) {\n                        containsMatch = candidate\n                    }\n                }\n            }\n\n        return exactMatch ?: containsMatch\n    }\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/QsbActionExecutor.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Traduz um QsbAction (saída do QsbIntentParser) em execução real:\n * resolve apps contra o AllAppsStore, resolve contatos contra\n * QsbContactResolver, monta o Intent certo para cada ação, e reporta\n * de volta ao chamador (OseWidgetView) o que fazer — incluindo pedir\n * uma permissão em falta, quando for o caso.\n *\n * Este arquivo não chama startActivity/requestPermissions diretamente:\n * devolve um ExecutionOutcome selado e quem efetivamente dispara a UI\n * é o chamador, que já tem acesso à Activity/View corretos. Mantém a\n * separação: parser não sabe de Android, executor não sabe de UI.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport android.content.Context\nimport android.content.Intent\nimport android.net.Uri\nimport com.android.launcher3.allapps.AllAppsStore\nimport com.android.launcher3.model.data.AppInfo\n\nsealed class QsbExecutionOutcome {\n    /** Intent pronto para ser disparado pelo chamador. */\n    data class Launch(val intent: Intent) : QsbExecutionOutcome()\n\n    /** Falta uma permissão de runtime para completar a ação. */\n    data class NeedsPermission(val permission: String, val retryAction: QsbAction) :\n        QsbExecutionOutcome()\n\n    /** Reconheceu a intenção mas não conseguiu resolver o alvo (app/contato). */\n    data class ResolutionFailed(val reason: QsbFailureReason) : QsbExecutionOutcome()\n\n    /** Não reconheceu nenhum comando — chamador decide fallback. */\n    data object Unrecognized : QsbExecutionOutcome()\n}\n\nenum class QsbFailureReason {\n    APP_NOT_FOUND,\n    CONTACT_NOT_FOUND,\n}\n\nobject QsbActionExecutor {\n\n\n    @JvmStatic\n    fun execute(context: Context, action: QsbAction, appsStore: AllAppsStore): QsbExecutionOutcome =\n        when (action) {\n            is QsbAction.Unrecognized -> QsbExecutionOutcome.Unrecognized\n\n            is QsbAction.OpenApp -> resolveApp(appsStore, action.appQuery)?.let {\n                QsbExecutionOutcome.Launch(it.intent)\n            } ?: QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.APP_NOT_FOUND)\n\n            is QsbAction.SearchInApp ->\n                resolveApp(appsStore, action.appQuery)?.let { app ->\n                    QsbExecutionOutcome.Launch(buildSearchIntent(context, app, action.query))\n                } ?: QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.APP_NOT_FOUND)\n\n            is QsbAction.CallNumber ->\n                QsbExecutionOutcome.Launch(buildCallIntent(action.number))\n\n            is QsbAction.CallContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildCallIntent(number)\n            }\n\n            is QsbAction.WhatsAppNumber ->\n                QsbExecutionOutcome.Launch(buildWhatsAppIntent(action.number, action.message))\n\n            is QsbAction.WhatsAppContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildWhatsAppIntent(number, action.message)\n            }\n\n            is QsbAction.SmsNumber ->\n                QsbExecutionOutcome.Launch(buildSmsIntent(action.number, action.message))\n\n            is QsbAction.SmsContact -> resolveContactOrRequestPermission(context, action, action.contactQuery) { number ->\n                buildSmsIntent(number, action.message)\n            }\n        }\n\n    /**\n     * Compartilhado pelos três tipos de ação "por contato": checa\n     * permissão, resolve o nome, e delega a montagem do Intent final\n     * para [buildIntent] uma vez que o número é conhecido. Devolve\n     * NeedsPermission com a própria [action] original em\n     * [QsbExecutionOutcome.NeedsPermission.retryAction] para o\n     * chamador poder re-executar exatamente o mesmo comando assim que\n     * a permissão for concedida, sem o usuário ter que digitar de novo.\n     */\n    private inline fun resolveContactOrRequestPermission(\n        context: Context,\n        action: QsbAction,\n        contactQuery: String,\n        buildIntent: (phoneNumber: String) -> Intent,\n    ): QsbExecutionOutcome {\n        if (!QsbContactResolver.hasContactsPermission(context)) {\n            return QsbExecutionOutcome.NeedsPermission(android.Manifest.permission.READ_CONTACTS, action)\n        }\n        val resolved = QsbContactResolver.resolve(context, contactQuery)\n            ?: return QsbExecutionOutcome.ResolutionFailed(QsbFailureReason.CONTACT_NOT_FOUND)\n        return QsbExecutionOutcome.Launch(buildIntent(resolved.phoneNumber))\n    }\n\n    private fun resolveApp(appsStore: AllAppsStore, query: String): AppInfo? {\n        val apps = appsStore.apps ?: emptyArray()\n        val queryLower = query.trim().lowercase()\n\n        apps.firstOrNull { it.title?.toString()?.lowercase() == queryLower }?.let { return it }\n        apps.firstOrNull { it.title?.toString()?.lowercase()?.startsWith(queryLower) == true }\n            ?.let { return it }\n        apps.firstOrNull { it.title?.toString()?.lowercase()?.contains(queryLower) == true }\n            ?.let { return it }\n        return null\n    }\n\n    private fun buildCallIntent(number: String): Intent =\n        Intent(Intent.ACTION_CALL, Uri.parse("tel:$number"))\n\n    private fun buildSmsIntent(number: String, message: String): Intent =\n        Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:$number")).apply {\n            if (message.isNotBlank()) putExtra("sms_body", message)\n        }\n\n    /**\n     * Usa o esquema de deep link público do WhatsApp (api.whatsapp.com/send)\n     * em vez de um Intent de package explícito — funciona tanto com\n     * WhatsApp quanto WhatsApp Business (o usuário escolhe se tiver os\n     * dois), e não exige declarar consulta de pacote específico no\n     * Manifest (Android 11+ visibilidade de pacotes).\n     */\n    private fun buildWhatsAppIntent(number: String, message: String): Intent {\n        val digitsOnly = number.filter { it.isDigit() }\n        val uriBuilder = Uri.parse("https://api.whatsapp.com/send").buildUpon()\n        uriBuilder.appendQueryParameter("phone", digitsOnly)\n        if (message.isNotBlank()) uriBuilder.appendQueryParameter("text", message)\n        return Intent(Intent.ACTION_VIEW, uriBuilder.build())\n    }\n\n    /**\n     * Pesquisa dentro de um app específico. Tenta primeiro\n     * ACTION_WEB_SEARCH restrito ao pacote do app (padrão que\n     * navegadores e vários apps de busca reconhecem, com o texto em\n     * SearchManager.QUERY). Só usa setPackage() se o PackageManager\n     * confirmar que o próprio app resolve essa action — sem essa\n     * checagem, setPackage() para um app sem esse handler derruba o\n     * launcher com ActivityNotFoundException em vez de abrir algo.\n     * Sem handler de busca dedicado, cai para abrir o app normalmente\n     * (o intent principal dele) — nunca abre um app diferente do\n     * pedido, só não consegue pré-preencher a pesquisa.\n     */\n    private fun buildSearchIntent(context: Context, app: AppInfo, query: String): Intent {\n        val packageName = app.componentName?.packageName\n        if (packageName != null) {\n            val webSearchIntent =\n                Intent(Intent.ACTION_WEB_SEARCH).apply {\n                    putExtra(android.app.SearchManager.QUERY, query)\n                    setPackage(packageName)\n                }\n            val resolved =\n                context.packageManager.resolveActivity(webSearchIntent, android.content.pm.PackageManager.MATCH_DEFAULT_ONLY)\n            if (resolved != null) return webSearchIntent\n        }\n        return app.intent\n    }\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/XaulinXsQsbPermissionCallback.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Ponte estática de curtíssima duração entre XaulinXsQsbPermissionActivity\n * (que efetivamente pede a permissão ao sistema) e o diálogo do Modo\n * Texto na QSB (que precisa reexecutar o comando original assim que a\n * permissão é concedida). Vive só entre "usuário tocou em Conceder" e\n * "resultado do diálogo do sistema voltou" — sempre limpo logo depois\n * de usado, nunca fica pendurado com uma referência antiga.\n */\npackage com.xaulinxs.customizations.qsb\n\nobject XaulinXsQsbPermissionCallback {\n\n    /**\n     * Callback de concessão. Setado pela QSB antes de abrir\n     * XaulinXsQsbPermissionActivity, chamado por ela quando o usuário\n     * concede a permissão, e sempre limpo (null) logo em seguida —\n     * tanto em concessão quanto em negação — para nunca reter o\n     * [android.content.Context] da View/Activity que o criou além do\n     * necessário.\n     */\n    @Volatile\n    var onGranted: ((QsbAction) -> Unit)? = null\n\n    @JvmStatic\n    fun consumeIfGranted(action: QsbAction) {\n        val callback = onGranted\n        onGranted = null\n        callback?.invoke(action)\n    }\n\n    @JvmStatic\n    fun clear() {\n        onGranted = null\n    }\n}\n',
    'modules/customizations/src/com/xaulinxs/customizations/qsb/XaulinXsQsbPermissionActivity.kt': '/*\n * XaulinXs Customizations — não faz parte do AOSP original.\n *\n * Activity transparente (tema ProxyActivityStarterTheme, já usado por\n * outras activities "de passagem" do próprio AOSP neste projeto) cujo\n * único propósito é pedir uma permissão de runtime em nome da QSB\n * Inteligente e devolver o resultado.\n *\n * Existe como Activity dedicada, e não como pedido direto pelo\n * Launcher, porque Launcher.java não implementa\n * onRequestPermissionsResult — adicionar esse override lá mexeria num\n * arquivo grande do AOSP com alto risco de conflito em futuras\n * atualizações do upstream. Isolar em uma Activity nova do pacote\n * XaulinXs Customizations mantém a mudança 100% contida.\n */\npackage com.xaulinxs.customizations.qsb\n\nimport android.app.Activity\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.PackageManager\nimport android.os.Bundle\nimport androidx.core.app.ActivityCompat\nimport androidx.core.content.IntentCompat\n\nclass XaulinXsQsbPermissionActivity : Activity() {\n\n    private lateinit var permission: String\n    private lateinit var pendingAction: QsbAction\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n\n        val permissionExtra = intent.getStringExtra(EXTRA_PERMISSION)\n        val actionExtra = IntentCompat.getSerializableExtra(intent, EXTRA_ACTION, QsbAction::class.java)\n        if (permissionExtra == null || actionExtra == null) {\n            // Extras ausentes/corrompidos (não deveria acontecer — só\n            // este arquivo constrói o Intent via newIntent()) — sem\n            // dado suficiente para pedir nada, encerra sem travar o\n            // usuário numa tela vazia.\n            XaulinXsQsbPermissionCallback.clear()\n            finish()\n            return\n        }\n        permission = permissionExtra\n        pendingAction = actionExtra\n\n        ActivityCompat.requestPermissions(this, arrayOf(permission), REQUEST_CODE)\n    }\n\n    override fun onRequestPermissionsResult(\n        requestCode: Int,\n        permissions: Array<out String>,\n        grantResults: IntArray,\n    ) {\n        super.onRequestPermissionsResult(requestCode, permissions, grantResults)\n        if (requestCode != REQUEST_CODE) {\n            finish()\n            return\n        }\n        val granted = grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED\n        if (granted) {\n            XaulinXsQsbPermissionCallback.consumeIfGranted(pendingAction)\n        } else {\n            XaulinXsQsbPermissionCallback.clear()\n        }\n        finish()\n    }\n\n    companion object {\n        private const val REQUEST_CODE = 7101\n        private const val EXTRA_PERMISSION = "xaulinxs_qsb_permission"\n        private const val EXTRA_ACTION = "xaulinxs_qsb_action"\n\n        @JvmStatic\n        fun newIntent(context: Context, permission: String, action: QsbAction): Intent =\n            Intent(context, XaulinXsQsbPermissionActivity::class.java).apply {\n                putExtra(EXTRA_PERMISSION, permission)\n                putExtra(EXTRA_ACTION, action)\n            }\n    }\n}\n',
}

