def run(cmd, cwd):
    result = subprocess.run(cmd, cwd=cwd, text=True)
    if result.returncode != 0:
        sys.exit(f"Comando falhou: {' '.join(cmd)}")


def apply_new_files(repo):
    """Cria os arquivos novos do modulo QSB Inteligente. Idempotente por
    conteudo exato: se o arquivo ja existe com o mesmo conteudo, pula;
    se existe com conteudo diferente, avisa e NAO sobrescreve (evita
    apagar uma edicao manual do usuario sem ele saber)."""
    created, already, conflict = [], [], []
    for rel_path, content in NEW_FILES.items():
        target = repo / rel_path
        if target.is_file():
            existing = target.read_text(encoding="utf-8")
            if existing == content:
                already.append(rel_path)
            else:
                conflict.append(rel_path)
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        created.append(rel_path)
    return created, already, conflict


def apply_patches(repo):
    applied_now, already_applied, failed = [], [], []
    for fix in PATCHES:
        target = repo / fix["path"]
        if not target.is_file():
            print(f"AVISO: {target} nao existe neste checkout -- pulando este fix.")
            continue

        current_content = target.read_text(encoding="utf-8")
        if fix["marker"] in current_content:
            already_applied.append(fix["path"])
            continue

        patch_filename = "_tmp_qsb_smart_patch.patch"
        patch_path = repo / patch_filename
        patch_path.write_text(fix["patch_content"], encoding="utf-8")

        check = subprocess.run(
            ["git", "apply", "--check", patch_filename],
            cwd=repo, text=True, capture_output=True,
        )
        if check.returncode != 0:
            failed.append((fix["path"], check.stderr.strip()))
            patch_path.unlink()
            continue

        run(["git", "apply", patch_filename], cwd=repo)
        patch_path.unlink()
        applied_now.append(fix["path"])
    return applied_now, already_applied, failed


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--repo", default="~/Launcher3",
        help="Caminho do checkout local (padrao: ~/Launcher3)",
    )
    parser.add_argument(
        "--skip-build", action="store_true",
        help="Nao rodar ./gradlew assembleNoQuickstepDebug ao final",
    )
    args = parser.parse_args()

    repo = Path(args.repo).expanduser().resolve()
    if not repo.is_dir():
        sys.exit(f"Repo nao encontrado em {repo}. Use --repo <caminho>.")

    print("Criando arquivos novos do modulo QSB Inteligente...")
    created, already_files, conflict_files = apply_new_files(repo)

    print("Aplicando patches nos arquivos existentes...")
    applied_now, already_patches, failed_patches = apply_patches(repo)

    print()
    if created:
        print("Arquivos novos criados:")
        for p in created:
            print(f"  + {p}")
    if applied_now:
        print("Patches aplicados agora:")
        for p in applied_now:
            print(f"  + {p}")
    if already_files or already_patches:
        print("Ja estavam aplicados (idempotente, pulados):")
        for p in already_files + already_patches:
            print(f"  = {p}")
    if conflict_files:
        print("CONFLITO -- arquivo ja existe com conteudo DIFERENTE do esperado (NAO sobrescrito):")
        for p in conflict_files:
            print(f"  ! {p}")
        print(
            "  Se voce editou algum desses arquivos manualmente, me avise o que "
            "mudou para eu gerar um patch em cima do estado atual."
        )
    if failed_patches:
        print("Patches NAO aplicados:")
        for p, err in failed_patches:
            print(f"  ! {p}")
            last_line = err.splitlines()[-1] if err else "(sem detalhe)"
            print(f"    {last_line}")
        print(
            "\nPara os itens marcados com '!', descreva o que esta diferente "
            "nesse arquivo e eu gero um patch novo em cima do estado atual dele."
        )

    if not created and not applied_now and not failed_patches and not conflict_files:
        print("\nNada a fazer -- tudo ja estava aplicado.")

    if not args.skip_build:
        print("\nCompilando (./gradlew assembleNoQuickstepDebug)...")
        gradlew = repo / "gradlew"
        if not gradlew.is_file():
            sys.exit("gradlew nao encontrado no repo -- pulei o build.")
        run(["chmod", "+x", "gradlew"], cwd=repo)
        run(["./gradlew", "assembleNoQuickstepDebug"], cwd=repo)
        print("\nBuild OK.")
    else:
        print("\n--skip-build: pulei a compilacao.")

    print(
        "\nProximo passo -- instalar o APK debug e testar o Modo Texto da QSB:\n"
        "  1) 'abrir Spotify' -- deve continuar funcionando como antes\n"
        "  2) 'abrir Chrome e pesquisar gatos' -- abre o Chrome ja com a busca\n"
        "  3) 'ligar para <nome de um contato seu>' -- primeira vez deve pedir "
        "permissao de Contatos; conceda e o comando roda sozinho na sequencia\n"
        "  4) 'ligar para 11987654321' (numero direto) -- nao deve pedir "
        "permissao nenhuma\n"
        "  5) 'manda whatsapp pro <contato> dizendo oi' -- abre o WhatsApp "
        "ja na conversa certa com a mensagem preenchida\n"
        "  6) um texto qualquer sem nenhum comando (ex.: 'oi tudo bem') -- "
        "deve cair pro Modo Web normalmente, igual antes\n"
        "  7) se pedir permissao e voce negar, tentar de novo deve pedir "
        "de novo (nao deve travar nem crashar)"
    )


if __name__ == "__main__":
    main()
